private.reference_solution:
#include <cstdio>
#include <vector>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (std::scanf("%lld", &value) != 1) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    long long total = 0;
    long long best = values[0];
    long long worst = values[0];
    for (long long value : values) {
        total += value;
        if (value > best) best = value;
        if (value < worst) worst = value;
    }
    std::printf("sum=%lld max=%lld min=%lld\n", total, best, worst);
    return 0;
}

