    // 读取 n 个单词，map 统计词频后输出两行汇总
    return 0;
}

private.reference_solution:
#include <cstdio>
#include <map>
#include <string>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    std::map<std::string, long long> counts;
    for (int i = 0; i < n; i++) {
        char buffer[64];
        if (std::scanf("%63s", buffer) != 1) return 1;
        std::string word(buffer);
        if (word.size() < 1 || word.size() > 30) return 1;
        for (char ch : word) {
            if (ch < 'a' || ch > 'z') return 1;
        }
        counts[word]++;
    }
    std::string best_word;
    long long best_count = -1;
    for (const auto& entry : counts) {
        if (entry.second > best_count) {
            best_count = entry.second;
            best_word = entry.first;
        }
    }
    std::printf("%zu\n%s:%lld\n", counts.size(), best_word.c_str(), best_count);
    return 0;
}
